table(['기전 핵심 수치','주 집계','별도 재구성/합산'],[['번들 rammed N',KV['primaryGroups']['local/bundled']['rammedN'],KV['independentGroups']['local/bundled']['rammedN']],['그중 직전 판단 확인 N',KV['primaryGroups']['local/bundled']['priorN'],KV['independentGroups']['local/bundled']['priorN']],['직전 빈 출구 ≥2 N',KV['primaryGroups']['local/bundled']['priorFree2plus'],KV['independentGroups']['local/bundled']['priorFree2plus']],['직전 L2 N',KV['primaryGroups']['local/bundled']['priorLen2'],KV['independentGroups']['local/bundled']['priorLen2']],['접촉 step ≥2 N',KV['primaryGroups']['local/bundled']['fatalStep2plus'],KV['independentGroups']['local/bundled']['fatalStep2plus']]]+[[f'default_small trap: {label}',KV['primaryGroups']['local/default_small'][field],KV['independentGroups']['local/default_small'][field]] for field,label in [('trapN','전체'),('trapAnyAlly','아군 조각 인접'),('trapAllyBody','아군 몸 인접'),('trapAllyHead','아군 머리 인접'),('trapEnemyBody','적 몸 인접')]]), '',
